"""Writes the command reference as the static HTML help that ships in the packages (wiki.py help).

The layout is that of the help of Blitz3D, so tools and habits that open <install>/help/index.html keep working:

  index.html                         Welcome page with the links to everything below.
  credits.html
  commands/index.htm                 Frameset: command_list.htm on the left, main.htm on the right.
  commands/command_list*.htm         The menu: 2D and 3D by category (command_list_<2d|3d>_cat_<n>.htm) and A-Z
                                     (command_list_<2d|3d>_a-z_<letter>.htm).
  commands/2d_commands/<Name>.htm    One page per command. 2d_commands holds Language Features, BlitzBasic and BlitzPlus, 3d_commands Blitz3D.
  commands/2d_examples/<Name>.bb     The first example of each command, as the original links it from the page.
  commands/css/                      commands.css (pages) and menu.css (menu).
  language/index.html                Frameset with title.html, navbar.html and the page on the right.
  language/<Page>.html               The pages that are not commands (Language, Types, Differences, ...).
  media/                             The images and animations that the pages use.

Everything is made from the same text as the wiki, so the help is generated while packaging and never committed.
"""
import html
import os
import re
import shutil

import categories

ESC = html.escape


# --- Markdown --------------------------------------------------------------------------------------------------------

class Links:
    """Resolves the targets of wiki links ([Name](Name), [[Name]]) from the page that links to them."""

    def __init__(self, commands, pages, prefix):
        self.commands = {c.name: c for c in commands}
        self.pages = set(pages)
        self.prefix = prefix  # How to get from the page to the help folder: "../../" from commands/2d_commands/.

    def target(self, name, current_dir):
        """Returns the href for a wiki page name, or None when the help has no such page."""
        if name == "Command-Index":
            return self.prefix + "commands/command_list_2d_a-z.htm"
        if name in self.commands:
            c = self.commands[name]
            return "%scommands/%s_commands/%s.htm" % (self.prefix, side(c), name)
        if name in self.pages:
            return "%slanguage/%s.html" % (self.prefix, name)
        for dialect in categories.CATEGORY_TEXT:
            if name == "%s-%s" % (dialect[0], dialect[1].replace(" ", "-")):
                return "%scommands/%s" % (self.prefix, category_file(dialect[0], dialect[1]))
        return None


def side(c):
    return "3d" if c.dialect == categories.B3D else "2d"


def category_order(side_name):
    wanted = (categories.B3D,) if side_name == "3d" else (categories.LANG, categories.BASIC, categories.PLUS)
    return [k for k in categories.CATEGORY_TEXT if k[0] in wanted]


def category_file(dialect, category):
    side_name = "3d" if dialect == categories.B3D else "2d"
    return "command_list_%s_cat_%d.htm" % (side_name, category_order(side_name).index((dialect, category)) + 1)


def inline(text, links, media):
    """Markdown inside a line: code, images, links, bold and italics. Anything that is already HTML is kept."""
    parts = []

    def keep(s):
        parts.append(s)
        return "\x00%d\x00" % (len(parts) - 1)

    text = re.sub(r"`([^`]+)`", lambda m: keep("<code>%s</code>" % ESC(m.group(1), quote=False)), text)
    text = re.sub(r"<!--.*?-->", "", text)
    text = re.sub(r"(<[a-zA-Z/][^>]*>)", lambda m: keep(rewrite_html(m.group(1), links, media)), text)

    def image(m):
        media.add(m.group(2))
        return keep('<img src="%s%s" alt="%s">' % (links.prefix, m.group(2), ESC(m.group(1))))

    text = re.sub(r"!\[([^\]]*)\]\(([^)\s]+)\)", image, text)

    def link(label, name):
        name, _, anchor = name.partition("#")
        if name.startswith("media/"):
            media.add(name)
            name = links.prefix + name
        href = links.target(name, None) if re.fullmatch(r"[A-Za-z0-9_-]+", name) else name
        if href is None:
            return label
        return keep('<a href="%s%s">%s</a>' % (href, "#" + anchor if anchor and href.endswith(".html") else "", label))

    text = re.sub(r"\[\[([^\]|]+)\]\]", lambda m: link(ESC(m.group(1).replace("-", " ")), m.group(1)), text)
    text = re.sub(r"\[([^\]]+)\]\(([^)\s]+)\)", lambda m: link(m.group(1), m.group(2)), text)
    text = ESC(text, quote=False)
    text = re.sub(r"\*\*(.+?)\*\*", r"<b>\1</b>", text)
    text = re.sub(r"(?<![\w*])\*([^*\s][^*]*?)\*(?![\w*])", r"<i>\1</i>", text)
    text = re.sub(r"(?<![\w])_([^_\s][^_]*?)_(?![\w])", r"<i>\1</i>", text)
    return re.sub("\x00(\\d+)\x00", lambda m: parts[int(m.group(1))], text)


def rewrite_html(tag, links, media):
    def src(m):
        if m.group(2).startswith("media/"):
            media.add(m.group(2))
            return '%s"%s%s"' % (m.group(1), links.prefix, m.group(2))
        return m.group(0)

    return re.sub(r'(src=)"([^"]+)"', src, tag)


def markdown(text, links, media, level=1):
    """Converts the Markdown subset the wiki text uses to HTML. level is the heading level of a '#'."""
    lines = text.split("\n")
    out, i = [], 0
    para = []

    def flush():
        if para:
            out.append("<p>%s</p>" % inline(" ".join(para), links, media))
            para.clear()

    while i < len(lines):
        line = lines[i]
        if line.startswith("```"):
            flush()
            lang, code, i = line[3:].strip(), [], i + 1
            while i < len(lines) and not lines[i].startswith("```"):
                code.append(lines[i])
                i += 1
            code = [x for x in code if not re.match(r"^;(media .*|run)$", x)]
            out.append("<pre>%s</pre>" % ESC("\n".join(code)))
        elif not line.strip():
            flush()
        elif re.match(r"^#{1,6} ", line):
            flush()
            n = len(line) - len(line.lstrip("#"))
            out.append("<h%d>%s</h%d>" % (n + level - 1, inline(line[n + 1:], links, media), n + level - 1))
        elif line.startswith("|"):
            flush()
            rows = []
            while i < len(lines) and lines[i].startswith("|"):
                rows.append([c.strip() for c in lines[i].strip().strip("|").split("|")])
                i += 1
            i -= 1
            out.append("<table>")
            for r, row in enumerate(rows):
                if r == 1 and all(re.fullmatch(r":?-+:?", c) for c in row):
                    continue
                tag = "th" if r == 0 else "td"
                out.append("<tr>%s</tr>" % "".join("<%s>%s</%s>" % (tag, inline(c, links, media), tag) for c in row))
            out.append("</table>")
        elif re.match(r"^\s*([*-]|\d+\.) ", line):
            flush()
            tag = "ol" if re.match(r"^\s*\d+\. ", line) else "ul"
            items = []
            while i < len(lines) and re.match(r"^\s*([*-]|\d+\.) ", lines[i]):
                items.append(re.sub(r"^\s*([*-]|\d+\.) ", "", lines[i]))
                i += 1
            i -= 1
            out.append("<%s>%s</%s>" % (tag, "".join("<li>%s</li>" % inline(x, links, media) for x in items), tag))
        elif line.startswith("<") and not re.match(r"^<(a|b|i|code|img|em|strong)[ >]", line):
            flush()
            out.append(inline(line, links, media))
        else:
            para.append(line.strip())
        i += 1
    flush()
    return "\n".join(out)


# --- Pages -----------------------------------------------------------------------------------------------------------

PAGE = ("<html>\n<head>\n<title>%(title)s</title>\n<link rel=stylesheet href=%(css)s type=text/css>\n</head>\n"
        "<body>\n%(body)s\n</body>\n</html>\n")


def write(path, text):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(text)


def table(inner):
    return "<table>\n<tr>\n<td>\n%s\n</td>\n</tr>\n</table>" % inner


def command_html(c, siblings, links, media, doc, free, split_text, related, product):
    media_lines = re.findall(r"^!\[[^\]]*\]\([^)]+\)[ \t]*$", free, re.M)
    free = re.sub(r"^!\[[^\]]*\]\([^)]+\)[ \t]*\n?", "", free, flags=re.M).strip()
    m = re.search(r"^```", free, re.M)
    description, examples = (free[:m.start()], free[m.start():]) if m else (free, "")
    sig = c.signature()
    out = ["<h1>%s%s</h1>" % (ESC(sig), ESC(c.mark))]
    if c.params:
        rows = ["<b>%s</b> (%s%s) - %s" % (ESC(n), t if " " in t else "In " + t, ", optional, default %s" % ESC(d) if d else "",
                                           inline(doc["param"].get(n, ""), links, media)) for t, n, d in c.params]
        out += ["<h1>Parameters</h1>", table("<br />\n".join(rows))]
    if doc["returns"]:
        out += ["<h1>Returns</h1>", table(inline(doc["returns"], links, media))]
    out += ["<h1>Description</h1>",
            table(markdown(description, links, media) if description.strip() else "Not documented yet.")]
    if c.extension:
        out[-1] = table("<b>%s</b> This command does not exist in the original Blitz products. BlitzLLVM adds it."
                        % ESC(c.mark.strip()) + markdown(description, links, media))
    if doc["gap"]:
        out += ["<h1>Differences</h1>", table("<ul>%s</ul>" % "".join("<li>%s</li>" % inline(g, links, media)
                                                                       for g in doc["gap"]))]
    if examples:
        first = re.search(r"```blitzbasic\n(.*?)```", examples, re.S)
        title = "Example"
        if first:
            title = '<a href=../%s_examples/%s.bb>Example</a>' % (side(c), c.name)
        out += ["<h1>%s</h1>" % title, table(markdown(examples, links, media))]
    if media_lines:
        out += ["<h1>Media</h1>", table(markdown("\n\n".join(media_lines), links, media))]
    rel = ", ".join(inline("[%s](%s)" % (o.name, o.name), links, media) for o in related(c, siblings))
    out += ["<h1>Related Commands</h1>", table(rel), "<br>",
            "<a target=_top href=../index.htm>Index</a><br>"]
    return PAGE % {"title": "%s Docs" % product, "css": "../css/commands.css", "body": "\n".join(out)}


MENU_HEAD = """<a href=command_list_2d_cat.htm>2D - Category</a>
<br>
<a href=command_list_3d_cat.htm>3D - Category</a>
<br>
<br>
<a href=command_list_2d_a-z.htm>2D - A-Z</a>
<br>
<a href=command_list_3d_a-z.htm>3D - A-Z</a>
<br>
<br>
<a href=../language/index.html target=_top>Language Reference</a>
<br>
<br>
<a target=_top href=index.htm>Index</a>
<hr>
"""


def menu(name, body):
    write(name, PAGE % {"title": "BlitzLLVM Docs", "css": "css/menu.css",
                        "body": "<h1>Command Ref.</h1>\n" + MENU_HEAD + body})


def command_list(out, commands):
    """The menu pages: the category pages and the A-Z pages of 2D and 3D, each with its own list open."""
    cmds_dir = os.path.join(out, "commands")
    for s in ("2d", "3d"):
        cats = category_order(s)
        by_cat = {k: sorted((c for c in commands if (c.dialect, c.category) == k), key=lambda c: c.name.lower())
                  for k in cats}

        def items(cs):
            return "<ul>%s</ul>" % "".join('<li><a href=%s_commands/%s.htm target=main>%s</a><br>' % (s, c.name, ESC(c.name + c.mark))
                                           for c in cs)

        head = "".join("<li><a href=command_list_%s_cat_%d.htm>%s</a><br>\n" % (s, n + 1, ESC(categories.display(k[1])))
                       for n, k in enumerate(cats))
        menu(os.path.join(cmds_dir, "command_list_%s_cat.htm" % s), head)
        for n, k in enumerate(cats):
            body = "".join(('<li><a href=command_list_%s_cat_%d.htm>%s</a><br>%s\n' %
                            (s, m + 1, ESC(categories.display(j[1])), items(by_cat[j]) if m == n else ""))
                           for m, j in enumerate(cats))
            menu(os.path.join(cmds_dir, "command_list_%s_cat_%d.htm" % (s, n + 1)), body)
        everything = sorted((c for k in cats for c in by_cat[k]), key=lambda c: c.name.lower())
        letters = sorted({c.name[0].upper() for c in everything})
        head = "".join("<li><a href=command_list_%s_a-z_%s.htm>%s</a><br>\n" % (s, l.lower(), l) for l in letters)
        menu(os.path.join(cmds_dir, "command_list_%s_a-z.htm" % s), head)
        for l in letters:
            body = "".join('<li><a href=command_list_%s_a-z_%s.htm>%s</a><br>%s\n' %
                           (s, m.lower(), m, items([c for c in everything if c.name[0].upper() == m]) if m == l else "")
                           for m in letters)
            menu(os.path.join(cmds_dir, "command_list_%s_a-z_%s.htm" % (s, l.lower())), body)
    write(os.path.join(cmds_dir, "command_list.htm"),
          PAGE % {"title": "BlitzLLVM Docs", "css": "css/menu.css", "body": "<h1>Command Ref.</h1>\n" + MENU_HEAD})


