FRAMES = ("<html>\n<head>\n<title>%s</title>\n</head>\n\n%s\n\n</html>\n")


def build_help(commands, out, wiki):
    """Writes the whole help into out. wiki is the wiki module (its text and page functions are used)."""
    shutil.rmtree(out, ignore_errors=True)
    media = set()
    cats = {}
    for c in commands:
        cats.setdefault((c.dialect, c.category), []).append(c)

    # Pages that are not commands: the hand-written feature pages and Differences, built into a scratch wiki first.
    sources = wiki.page_sources(commands)
    page_names = list(sources)
    for c in commands:
        s = side(c)
        links = Links(commands, page_names, "../../")
        free, doc = wiki.split_text(re.sub(r"^;(media .*|run)\n", "", c.text, flags=re.M))
        siblings = cats[(c.dialect, c.category)]
        product = "Blitz3D" if c.dialect == categories.B3D else "BlitzPlus" if c.dialect == categories.PLUS else "Blitz"
        write(os.path.join(out, "commands", s + "_commands", c.name + ".htm"),
              command_html(c, siblings, links, media, doc, free, wiki.split_text, wiki.related, product))
        first = re.search(r"```blitzbasic\n(.*?)```", free, re.S)
        if first:
            code = "\n".join(x for x in first.group(1).split("\n") if not re.match(r"^;(media .*|run|nocompile)$", x))
            write(os.path.join(out, "commands", s + "_examples", c.name + ".bb"), code.rstrip("\n") + "\n")

    command_list(out, commands)
    write(os.path.join(out, "commands", "css", "menu.css"), MENU_CSS)
    write(os.path.join(out, "commands", "css", "commands.css"), COMMANDS_CSS)
    write(os.path.join(out, "commands", "index.htm"), FRAMES % (
        "BlitzLLVM Docs",
        '<frameset cols="200,*">\n  <frame name="contents" target="main" scrolling="auto" src="command_list.htm">\n'
        '  <frame name="main" src="main.htm" scrolling="auto" target="_self">\n  <noframes>\n  <body>\n\n'
        '  <p>This page uses frames, but your browser does not support them.</p>\n\n  </body>\n  </noframes>\n</frameset>'))
    write(os.path.join(out, "commands", "main.htm"), PAGE % {
        "title": "BlitzLLVM Docs", "css": "css/menu.css",
        "body": "<h1>Command Reference</h1>\nThe commands of BlitzBasic, Blitz3D and BlitzPlus as BlitzLLVM implements them. "
                "Pick a list on the left. Commands that BlitzLLVM adds are marked %s. "
                "<a href=../language/Differences.html>How BlitzLLVM differs from the originals</a>." % ESC(wiki.EXTENSION_MARK)})

    # Language reference: every page that is not a command, with the original frameset around it.
    links = Links(commands, page_names, "../")
    nav = []
    for name, title, body in sources.values():
        text = markdown(body, links, media)
        write(os.path.join(out, "language", name + ".html"),
              PAGE % {"title": title, "css": "lang_ref.css", "body": text})
        nav.append((title, name))
    nav.sort(key=lambda p: (p[1] != "Language", p[0].lower()))
    write(os.path.join(out, "language", "lang_ref.css"), LANGUAGE_CSS)
    write(os.path.join(out, "language", "title.html"), PAGE % {
        "title": "Language Reference", "css": "lang_ref.css",
        "body": "<h1>BlitzLLVM Language Reference</h1>"})
    write(os.path.join(out, "language", "navbar.html"), PAGE % {
        "title": "Navigation", "css": "lang_ref.css",
        "body": "<a target=_top href=../index.html>Home</a><br><br>\n" + "<br>\n".join(
            '<a href=%s.html target=main>%s</a>' % (n, ESC(t)) for t, n in nav)})
    write(os.path.join(out, "language", "index.html"), FRAMES % (
        "BlitzLLVM Language Reference",
        '<frameset rows="56,*" frameborder=0 framespacing=0 border=0>\n'
        '<frame src="title.html" name="title" scrolling="no" marginwidth=4 marginheight=0 noresize>\n'
        '<frameset cols="160,*" frameborder=0 framespacing=0 border=0>\n'
        '<frame src="navbar.html" name="navbar" scrolling="auto" marginwidth=4 marginheight=0 noresize>\n'
        '<frame src="Language.html" name="main" scrolling="auto" marginwidth=4 marginheight=0 noresize>\n'
        '</frameset>\n</frameset>'))

    write(os.path.join(out, "index.html"), PAGE % {"title": "Welcome to BlitzLLVM", "css": "language/lang_ref.css", "body": (
        "<h1>Welcome to BlitzLLVM!</h1>\n<ul>\n"
        "<li><a href=commands/index.htm>Command Reference</a> - every command of BlitzBasic, Blitz3D and BlitzPlus.<br><br>\n"
        "<li><a href=language/index.html>Language Reference</a> - the language, types and the differences from the originals.<br><br>\n"
        "<li><a href=credits.html>Credits</a> - who did what.<br><br>\n</ul>")})
    write(os.path.join(out, "credits.html"), PAGE % {"title": "Credits", "css": "language/lang_ref.css", "body": (
        "<h1>Credits</h1>\nBlitzLLVM is made by Xaymar and its contributors. "
        "Blitz3D, BlitzPlus and BlitzBasic were made by Mark Sibly and Blitz Research Ltd., whose commands this "
        "software implements.<br><br>\nSee the licenses folder for the libraries BlitzLLVM uses.")})

    for m in sorted(media):
        src = os.path.join(wiki.WIKI, m)
        if os.path.exists(src):
            os.makedirs(os.path.dirname(os.path.join(out, m)), exist_ok=True)
            shutil.copyfile(src, os.path.join(out, m))
